namespace InventoryApp.Services;

public record EquipmentItem(
    int Id,
    string Name,
    string Location,
    DateTime LastInspected);

public interface IEquipmentService
{
    Task<List<EquipmentItem>> GetEquipmentAsync();
}

public class EquipmentService : IEquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate a slow data source
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new(1, "Hydraulic Press",     "Building A - Bay 3",  new DateTime(2026, 6, 10)),
            new(2, "CNC Lathe",           "Building B - Shop 1", new DateTime(2026, 5, 22)),
            new(3, "Overhead Crane 10T",  "Warehouse C",         new DateTime(2026, 4, 15)),
            new(4, "Arc Welder MIG-400",  "Building A - Bay 1",  new DateTime(2026, 6, 1)),
            new(5, "Forklift #7",         "Yard - Dock 2",      new DateTime(2026, 3, 30)),
            new(6, "Band Saw 18\"",       "Building B - Shop 2", new DateTime(2026, 5, 5)),
            new(7, "Air Compressor 200L", "Utility Room",        new DateTime(2026, 6, 20)),
            new(8, "Drill Press",         "Building A - Bay 2",  new DateTime(2026, 2, 14)),
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@using InventoryApp.Services
@inject IEquipmentService EquipmentService
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private const string PersistenceKey = "inventory-items";
    private List<EquipmentItem>? _items;
    private PersistingComponentStateSubscription _subscription;

    protected override async Task OnInitializedAsync()
    {
        // Subscribe so the prerender pass persists our data into the page.
        _subscription = ApplicationState.RegisterOnPersisting(PersistData);

        // If data was already persisted during prerender, reuse it
        // instead of calling the service a second time.
        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>(
                PersistenceKey, out var restored))
        {
            _items = restored;
        }
        else
        {
            _items = await EquipmentService.GetEquipmentAsync();
        }
    }

    private Task PersistData()
    {
        ApplicationState.PersistAsJson(PersistenceKey, _items);
        return Task.CompletedTask;
    }

    public void Dispose() => _subscription.Dispose();
}

